    },
    {
      "card_ids": ["C05"],
      "claim": "Patupilone, a macrocyclic lactone natural product, showed greater brain exposure than other tissues in rats and mice, supporting CNS penetration for lactone-containing terpenoid scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Periplogenin, a lactone-containing cardiac glycoside, was detected in rat brain after systemic administration, providing additional evidence that lactone-containing natural products can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: direct rat brain distribution evidence for ACT001 (the query) shows high brain concentrations after oral dosing that exceed plasma levels, and multiple structurally related lactone/terpenoid compounds independently cross the BBB.",
